CARDIO.register({"item":"p75","meta":{"num":"p75","label":"75","spe":"pneumo","short":"Addiction au tabac","title":"Addiction au tabac","section":"P","chapter":1,"pages":"4-16","sdd":[]},"objectives":[{"id":"p75-obj-01","rank":"A","rubric":"Définition","title":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","desc":""},{"id":"p75-obj-02","rank":"A","rubric":"Définition","title":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d'évaluer cette dépendance","desc":""},{"id":"p75-obj-03","rank":"B","rubric":"Définition","title":"Connaître la définition de la cigarette électronique","desc":""},{"id":"p75-obj-04","rank":"B","rubric":"Physiopathologie","title":"Connaître la toxicité de la nicotine, des goudrons et de la fumée de tabac","desc":""},{"id":"p75-obj-05","rank":"B","rubric":"Physiopathologie","title":"Connaître le mécanisme d'atteinte artérielle (thrombogénicité, vasomotricité, inflammation)","desc":""},{"id":"p75-obj-06","rank":"A","rubric":"Épidémiologie","title":"Connaître l'âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","desc":""},{"id":"p75-obj-07","rank":"B","rubric":"Épidémiologie","title":"Connaître les tendances épidémiologiques du tabagisme au cours du temps","desc":""},{"id":"p75-obj-08","rank":"A","rubric":"Épidémiologie","title":"Connaître l'épidémiologie du tabagisme chez les jeunes","desc":""},{"id":"p75-obj-09","rank":"A","rubric":"Épidémiologie","title":"Connaître l'épidémiologie du tabagisme chez les hommes et les femmes","desc":""},{"id":"p75-obj-10","rank":"A","rubric":"Épidémiologie","title":"Connaître l'épidémiologie du tabagisme chez la femme enceinte","desc":""},{"id":"p75-obj-11","rank":"A","rubric":"Épidémiologie","title":"Connaître les modes de consommation du tabac","desc":""},{"id":"p75-obj-12","rank":"A","rubric":"Épidémiologie","title":"Connaître l'ordre de grandeur du nombre de cas de cancer liés au tabac","desc":""},{"id":"p75-obj-13","rank":"A","rubric":"Épidémiologie","title":"Connaître la part du tabac dans la mortalité en France","desc":""},{"id":"p75-obj-14","rank":"A","rubric":"Épidémiologie","title":"Connaître la mortalité liée au tabagisme actif","desc":""},{"id":"p75-obj-15","rank":"A","rubric":"Épidémiologie","title":"Connaître l'impact sur la mortalité cardiovasculaire","desc":""},{"id":"p75-obj-16","rank":"A","rubric":"Épidémiologie","title":"Connaître l'épidémiologie du tabagisme et celles des principales maladies liées au tabac","desc":""},{"id":"p75-obj-17","rank":"A","rubric":"Épidémiologie","title":"Connaître l'épidémiologie du tabagisme passif, les grandes notions de sur-risque","desc":""},{"id":"p75-obj-18","rank":"B","rubric":"Épidémiologie","title":"Connaître les catégories socio-professionnelles (CSP) des fumeurs en France","desc":""},{"id":"p75-obj-19","rank":"A","rubric":"Diagnostic positif","title":"Savoir dépister la consommation de tabac","desc":""},{"id":"p75-obj-20","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités de diagnostic de la dépendance","desc":""},{"id":"p75-obj-21","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes de sevrage en tabac","desc":""},{"id":"p75-obj-22","rank":"A","rubric":"Diagnostic positif","title":"Connaître les complications médicales non psychiatriques","desc":""},{"id":"p75-obj-23","rank":"B","rubric":"Diagnostic positif","title":"Connaître le diagnostic des comorbidités psychiatriques et addictives","desc":""},{"id":"p75-obj-24","rank":"A","rubric":"Prise en charge","title":"Moment du sevrage : connaître la proposition d'aide à l'arrêt à chaque contact avec un professionnel de santé","desc":""},{"id":"p75-obj-25","rank":"A","rubric":"Prise en charge","title":"Connaître les moyens de prévention primaire et secondaire","desc":""},{"id":"p75-obj-26","rank":"A","rubric":"Prise en charge","title":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","desc":""},{"id":"p75-obj-27","rank":"A","rubric":"Prise en charge","title":"Connaître les outils institutionnels (tabac info service)","desc":""},{"id":"p75-obj-28","rank":"B","rubric":"Prise en charge","title":"Connaître les modalités de la prise en charge après un évènement aigu : infarctus du myocarde, décompensation respiratoire","desc":""},{"id":"p75-obj-29","rank":"B","rubric":"Prise en charge","title":"Savoir rechercher des comorbidités en fonction du terrain","desc":""},{"id":"p75-obj-30","rank":"B","rubric":"Prise en charge","title":"Connaître la prise en charge à long terme : les rechutes sont la règle, d'où la proposition systématique d'arrêt du tabac","desc":""},{"id":"p75-obj-31","rank":"B","rubric":"Prise en charge","title":"Connaître l'aide médicamenteuse autre que traitements substitutifs nicotiniques","desc":""},{"id":"p75-obj-32","rank":"B","rubric":"Prise en charge","title":"Savoir quand adresser un patient en consultation de tabacologie : premier recours, méthode des 5A (ask, assess, advise, assist and arrange)","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p75-qroc-001","type":"QROC","rank":"A","objective":"p75-obj-06","tags":["épidémiologie"],"difficulty":1,"question":"Quelle est la première cause de mortalité évitable en France et dans le monde ?","answer":"Le tabagisme (le tabac)","accept":["tabac","tabagisme","le tabac","le tabagisme"],"keywords":["tabac"],"explanation":"Le tabac est la 1re cause de mortalité évitable : plus de 75 000 décès par an en France, et un fumeur sur deux meurt d'une maladie liée au tabac.","src":"p. 5, 9"},{"id":"p75-qroc-002","type":"QROC","rank":"A","objective":"p75-obj-13","tags":["épidémiologie"],"difficulty":1,"question":"Environ combien de décès par an sont attribuables au tabac en France ?","answer":"Environ 75 000","accept":["75 000","75000","75 000 décès","75000 décès","75.000"],"keywords":["75"],"explanation":"Environ 75 000 décès en 2015 : près de 55 000 chez l'homme (19 % de ses décès) et 20 000 chez la femme (7 % de ses décès).","src":"p. 5, 9"},{"id":"p75-qroc-003","type":"QROC","rank":"A","objective":"p75-obj-14","tags":["épidémiologie"],"difficulty":1,"question":"Quelle proportion des fumeurs meurt prématurément d'une maladie liée au tabac ?","answer":"1 fumeur sur 2","accept":["un fumeur sur deux","un sur deux","1 sur 2","la moitié","50 %"],"keywords":["sur 2"],"explanation":"Un fumeur sur deux meurt d'une maladie due au tabac. Les décès attribuables se répartissent surtout entre cancers (46 000), maladies cardio-vasculaires (17 000) et maladies respiratoires (12 000).","src":"p. 5, 9"},{"id":"p75-qroc-004","type":"QROC","rank":"A","objective":"p75-obj-12","tags":["épidémiologie"],"difficulty":1,"question":"Quelle proportion de l'ensemble des cancers est attribuable au tabac ?","answer":"1 cancer sur 4","accept":["un cancer sur quatre","un sur quatre","1 sur 4","un quart","25 %"],"keywords":["sur 4"],"explanation":"Un cancer sur quatre est dû au tabac ; le cancer du poumon représente 32 000 des 46 000 décès par cancer attribuables au tabac.","src":"p. 9"},{"id":"p75-qroc-005","type":"QROC","rank":"A","objective":"p75-obj-16","tags":["épidémiologie","étiologie"],"difficulty":1,"question":"Quelle proportion des cancers du poumon est liée au tabac ?","answer":"80 %","accept":["80 %","80%","80","80 pour cent"],"keywords":["80"],"explanation":"80 % des cancers du poumon sont liés au tabac. Il n'existe pas de seuil de consommation sans risque : le risque dépend du nombre de cigarettes par jour et surtout de la durée du tabagisme.","src":"p. 9"},{"id":"p75-qroc-006","type":"QROC","rank":"A","objective":"p75-obj-16","tags":["épidémiologie"],"difficulty":1,"question":"Par combien le risque de cancer du poumon d'un fumeur est-il multiplié par rapport à un non-fumeur ?","answer":"De 10 à 15 fois","accept":["10 à 15","10-15","de 10 à 15","entre 10 et 15","10 à 15 fois"],"keywords":["10","15"],"explanation":"Un fumeur a 10 à 15 fois plus de risque de cancer du poumon qu'un non-fumeur. Le risque de cancer du poumon est aussi multiplié par 3 chez le patient BPCO.","src":"p. 9"},{"id":"p75-qroc-007","type":"QROC","rank":"A","objective":"p75-obj-15","tags":["épidémiologie","complications"],"difficulty":1,"question":"Par quel facteur le tabac multiplie-t-il le risque de maladie cardio-vasculaire ?","answer":"Par 20","accept":["20","x 20","x20","par 20","20 fois","multiplié par 20"],"keywords":["20"],"explanation":"Le tabac multiplie par 20 le risque de maladie cardio-vasculaire (cardiopathie ischémique, artériopathie, HTA, accident vasculaire cérébral, anévrysme de l'aorte) : hypoxie liée au CO, dysfonction endothéliale et agrégation plaquettaire.","src":"p. 9"},{"id":"p75-qroc-008","type":"QROC","rank":"A","objective":"p75-obj-06","tags":["épidémiologie"],"difficulty":1,"question":"En France en 2021, quelle proportion des adultes de 18 à 75 ans fume tous les jours ?","answer":"Environ 1 adulte sur 4","accept":["1 sur 4","un sur quatre","un quart","25 %","un adulte sur quatre"],"keywords":["sur 4"],"explanation":"En 2021, près d'un adulte sur trois fume et un sur quatre fume quotidiennement, soit environ 15 millions de fumeurs dont 12 millions de fumeurs quotidiens.","src":"p. 5, 7"},{"id":"p75-qroc-009","type":"QROC","rank":"A","objective":"p75-obj-02","tags":["physiopathologie","définition"],"difficulty":1,"question":"Quel constituant de la fumée de tabac est le principal responsable de la dépendance ?","answer":"La nicotine","accept":["nicotine","la nicotine"],"keywords":["nicotin"],"explanation":"La nicotine atteint très vite le cerveau et stimule les systèmes de récompense ; elle est l'agent de la dépendance mais n'est pas cancérigène en tant que telle (les cancers viennent surtout des goudrons).","src":"p. 5-6"},{"id":"p75-qroc-010","type":"QROC","rank":"B","objective":"p75-obj-04","tags":["physiopathologie"],"difficulty":1,"question":"Quelle substance de la fumée de tabac est la principale responsable des cancers ?","answer":"Les goudrons","accept":["goudron","goudrons","les goudrons"],"keywords":["goudron"],"explanation":"Les goudrons modifient les cellules épithéliales bronchiques. Piège : la nicotine est responsable de la dépendance, pas des cancers.","src":"p. 6"},{"id":"p75-qroc-011","type":"QROC","rank":"A","objective":"p75-obj-02","tags":["définition"],"difficulty":1,"question":"Quels sont les trois types de dépendance entraînés par le tabac ?","answer":"Physique (pharmacologique), psychologique, comportementale","accept":["physique, psychologique et comportementale","pharmacologique, psychologique et comportementale","physique psychologique comportementale","physique psychologique sociale"],"keywords":["physi","psycho","comportement"],"explanation":"Physique : nicotine sur les récepteurs cholinergiques nicotiniques et récompense. Psychologique : effets positifs recherchés (se relaxer, réfléchir, coupe-faim). Comportementale (ou sociale) : situations répétées associées à la cigarette.","src":"p. 6"},{"id":"p75-qroc-012","type":"QROC","rank":"A","objective":"p75-obj-02","tags":["définition","clinique"],"difficulty":2,"question":"Quel type de dépendance correspond aux situations répétées associées à la cigarette (moments de convivialité, café, alcool) qui déclenchent une envie « réflexe » de fumer ?","answer":"La dépendance comportementale (ou sociale)","accept":["comportementale","dépendance comportementale","sociale","dépendance sociale"],"keywords":["comportement"],"explanation":"À distinguer de la dépendance psychologique (effets positifs attendus de la cigarette) et de la dépendance physique (nicotine). Le craving reflète les dépendances psychologique et comportementale.","src":"p. 6, 13"},{"id":"p75-qroc-013","type":"QROC","rank":"A","objective":"p75-obj-20","tags":["diagnostic","définition"],"difficulty":1,"question":"Selon la CIM-10, combien de manifestations, présentes en même temps au cours de la dernière année, faut-il au minimum pour affirmer une dépendance à une substance ?","answer":"Au moins 3","accept":["3","trois","au moins 3","au moins trois","3 manifestations"],"keywords":["3"],"explanation":"Il faut au moins 3 manifestations parmi : désir compulsif, difficulté à contrôler l'usage, syndrome de sevrage, tolérance, abandon des autres intérêts avec temps accru consacré à la substance, poursuite malgré les conséquences nocives.","src":"p. 6"},{"id":"p75-qroc-014","type":"QROC","rank":"A","objective":"p75-obj-20","tags":["diagnostic"],"difficulty":1,"question":"Quel test permet d'évaluer la dépendance physique (pharmacologique) à la nicotine ?","answer":"Le test de Fagerström","accept":["fagerstrom","test de fagerstrom","fagerström","score de fagerstrom"],"keywords":["fagerstr"],"explanation":"Le test de Fagerström comporte 6 questions ; sa version simplifiée à 2 questions est plus utile en pratique.","src":"p. 5, 12"},{"id":"p75-qroc-015","type":"QROC","rank":"A","objective":"p75-obj-20","tags":["diagnostic"],"difficulty":2,"question":"Quelles sont les deux questions du test de Fagerström simplifié ?","answer":"Nombre de cigarettes par jour + délai réveil-1re cigarette","accept":["cigarettes par jour et délai avant la première cigarette","nombre de cigarettes par jour et délai réveil première cigarette","quantité par jour et délai après le réveil","délai réveil première cigarette et nombre de cigarettes par jour"],"keywords":["par jour","réveil"],"explanation":"La version simplifiée repose sur la quantité de cigarettes fumées par jour et sur le délai entre le réveil et la première cigarette ; chaque question est notée de 0 à 3.","src":"p. 5, 12"},{"id":"p75-qroc-016","type":"QROC","rank":"A","objective":"p75-obj-20","tags":["diagnostic"],"difficulty":2,"question":"Au test de Fagerström simplifié (score de 0 à 6), à partir de quel score parle-t-on de dépendance forte ?","answer":"4 à 6","accept":["4","4 à 6","4-6","à partir de 4","au moins 4"],"keywords":["4"],"explanation":"0-1 : non dépendant ; 2-3 : dépendance modérée ; 4-6 : dépendance forte.","src":"p. 12"},{"id":"p75-qroc-017","type":"QROC","rank":"A","objective":"p75-obj-20","tags":["diagnostic"],"difficulty":2,"question":"Quel délai entre le réveil et la première cigarette rapporte le score maximal (3 points) au test de Fagerström ?","answer":"Dans les 5 premières minutes","accept":["5 minutes","5 premières minutes","moins de 5 minutes","dans les 5 minutes","5 min"],"keywords":["5"],"explanation":"Première cigarette dans les 5 minutes = 3 points ; entre 6 et 30 min = 2 ; entre 31 et 60 min = 1 ; après 60 min = 0.","src":"p. 12"},{"id":"p75-qroc-018","type":"QROC","rank":"A","objective":"p75-obj-21","tags":["clinique"],"difficulty":1,"question":"Quel phénomène, qui apparaît dès l'arrêt du tabac à cause de la chute de la nicotinémie, est le principal facteur de rechute ?","answer":"Le syndrome de sevrage (signes de sevrage)","accept":["sevrage","syndrome de sevrage","signes de sevrage","symptômes de sevrage"],"keywords":["sevrage"],"explanation":"Les signes de sevrage (trouble de l'humeur, céphalées, insomnie, irritabilité, anxiété, difficultés de concentration, appétit accru ou prise de poids) peuvent être corrigés par le traitement substitutif.","src":"p. 13"},{"id":"p75-qroc-019","type":"QROC","rank":"A","objective":"p75-obj-21","tags":["clinique","définition"],"difficulty":1,"question":"Comment nomme-t-on la pulsion à consommer du tabac, reflet de la dépendance psychologique et comportementale ?","answer":"Le craving","accept":["craving","le craving"],"keywords":["craving"],"explanation":"Le craving est l'envie pressante de fumer, alors que les signes de sevrage font suite à la chute de la nicotinémie.","src":"p. 13"},{"id":"p75-qroc-020","type":"QROC","rank":"A","objective":"p75-obj-19","tags":["diagnostic","prévention"],"difficulty":1,"question":"Comment s'appelle la démarche de repérage précoce suivi d'une intervention brève, habituellement utilisée pour l'alcool ou le cannabis et applicable au tabac ?","answer":"RPIB (Repérage Précoce et Intervention Brève)","accept":["rpib","repérage précoce et intervention brève","repérage précoce intervention brève"],"keywords":["rpib"],"explanation":"Le RPIB s'applique à toutes les substances psychoactives, tabac compris ; la méthode des 5A en est une alternative. Le conseil minimal augmente le taux de sevrage.","src":"p. 11"},{"id":"p75-qroc-021","type":"QROC","rank":"A","objective":"p75-obj-19","tags":["définition","diagnostic"],"difficulty":1,"question":"Après combien de temps d'arrêt total et définitif parle-t-on le plus communément d'ex-fumeur (fumeur sevré) ?","answer":"12 mois","accept":["12 mois","1 an","un an","douze mois"],"keywords":["12"],"explanation":"Le délai le plus admis est de 12 mois. Un fumeur actif est un fumeur non sevré depuis 12 mois ; un non-fumeur a fumé moins de 100 cigarettes au cours de sa vie.","src":"p. 7"},{"id":"p75-qroc-022","type":"QROC","rank":"A","objective":"p75-obj-19","tags":["diagnostic"],"difficulty":2,"question":"Un patient fume 30 cigarettes par jour depuis 20 ans. Combien de paquets-années cela représente-t-il ?","answer":"30 paquets-années","accept":["30","30 pa","30 paquets-années","30 paquets années"],"keywords":["30"],"explanation":"30 cigarettes = 1,5 paquet de 20 ; 1,5 × 20 ans = 30 paquets-années. Mais le paquet-année évalue mal le risque : la durée pèse plus que la quantité.","src":"p. 11"},{"id":"p75-qroc-023","type":"QROC","rank":"A","objective":"p75-obj-19","tags":["pièges","épidémiologie"],"difficulty":2,"question":"Dans l'évaluation du risque de cancer lié au tabac, quel paramètre est le plus déterminant : la quantité quotidienne ou la durée d'exposition ?","answer":"La durée d'exposition","accept":["durée","la durée","durée du tabagisme","durée d'exposition","durée de l'exposition"],"keywords":["durée"],"explanation":"La quantité majore le risque avec un facteur à la puissance 2, la durée avec un facteur à la puissance 4 : 10 cigarettes par jour pendant 20 ans et 20 cigarettes par jour pendant 10 ans font 10 paquets-années chacun mais ne se valent pas.","src":"p. 11-12"},{"id":"p75-qroc-024","type":"QROC","rank":"A","objective":"p75-obj-19","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Quelle mesure simple et non déclarative permet de vérifier une consommation de tabac récente (moins de 24 h) ?","answer":"La mesure du CO dans l'air expiré","accept":["co expiré","monoxyde de carbone expiré","mesure du co","co dans l'air expiré","monoxyde de carbone dans l'air expiré","co air expiré"],"keywords":["expir"],"explanation":"Le CO expiré est un bon marqueur du tabagisme des dernières heures et s'utilise en tabacologie ; son avantage est de ne pas reposer sur les déclarations du patient.","src":"p. 7, 12"},{"id":"p75-qroc-025","type":"QROC","rank":"A","objective":"p75-obj-27","tags":["prévention","suivi"],"difficulty":1,"question":"Quel est le numéro de la ligne téléphonique gratuite de Tabac Info Service, qui propose un accompagnement personnalisé ?","answer":"3989","accept":["3989","39 89","le 3989"],"keywords":["3989"],"explanation":"Tabac Info Service (site internet et ligne 3989) propose un coaching personnalisé ; on y oriente les patients dès le conseil minimal.","src":"p. 11, 15"},{"id":"p75-qroc-026","type":"QROC","rank":"A","objective":"p75-obj-24","tags":["prévention","grossesse"],"difficulty":2,"question":"Quelles sont les trois situations impliquant une attention particulière pour proposer un sevrage tabagique rapide ?","answer":"Grossesse, chirurgie programmée, maladie liée au tabac","accept":["grossesse, chirurgie programmée et maladie liée au tabac","grossesse chirurgie programmée maladie liée au tabac","grossesse, chirurgie programmée et découverte d'une maladie liée au tabac"],"keywords":["grossesse","chirurgi","maladie"],"explanation":"L'arrêt est à organiser quelle que soit la motivation du fumeur, et plus particulièrement en cas de grossesse, de chirurgie programmée ou de maladie liée au tabac (découverte ou maladie sévère).","src":"p. 5, 11"},{"id":"p75-qroc-027","type":"QROC","rank":"A","objective":"p75-obj-24","tags":["prévention","traitement"],"difficulty":2,"question":"Combien de temps avant une chirurgie programmée faut-il arrêter de fumer pour diminuer la morbi-mortalité opératoire ?","answer":"6 à 8 semaines avant","accept":["6 à 8 semaines","6-8 semaines","6 à 8","six à huit semaines"],"keywords":["6","8"],"explanation":"Un arrêt 6 à 8 semaines avant l'intervention diminue la morbi-mortalité opératoire ; la chirurgie programmée fait partie des situations où le sevrage est particulièrement à proposer.","src":"p. 11"},{"id":"p75-qroc-028","type":"QROC","rank":"A","objective":"p75-obj-24","tags":["prévention","pièges"],"difficulty":1,"question":"Chez quels fumeurs l'arrêt du tabac doit-il être organisé ?","answer":"Tous, quelle que soit leur motivation","accept":["quelle que soit la motivation","quelle que soit leur motivation","tous les fumeurs","tous les fumeurs quelle que soit leur motivation"],"keywords":["motivation"],"explanation":"Chaque consultation avec un professionnel de santé est l'occasion d'un dépistage et d'un conseil d'arrêt : on ne réserve pas l'aide aux fumeurs déjà motivés.","src":"p. 5"},{"id":"p75-qroc-029","type":"QROC","rank":"A","objective":"p75-obj-08","tags":["épidémiologie"],"difficulty":2,"question":"En 2017, à quel âge moyen les adolescents expérimentaient-ils le tabac ?","answer":"14,4 ans (environ 14 ans)","accept":["14,4 ans","14 ans","14,4","environ 14 ans"],"keywords":["14"],"explanation":"La consommation quotidienne débute en moyenne à 15,1 ans ; chez les élèves de 3e, l'expérimentation est passée de 51,8 % en 2010 à 29,1 % en 2021, et l'usage quotidien de 15,6 % à 3,7 %.","src":"p. 8"},{"id":"p75-qroc-030","type":"QROC","rank":"A","objective":"p75-obj-26","tags":["traitement","pièges"],"difficulty":1,"question":"Quelles sont les contre-indications des substituts nicotiniques ?","answer":"Aucune (même après un événement cardio-vasculaire aigu)","accept":["aucune","aucune contre-indication","pas de contre-indication","il n'y en a pas"],"keywords":["aucun"],"explanation":"Les substituts nicotiniques n'ont globalement aucune contre-indication, y compris après un événement cardio-vasculaire aigu ou chez la femme enceinte ; leur indication est large dès qu'il existe une dépendance.","src":"p. 5, 13"},{"id":"p75-qroc-031","type":"QROC","rank":"A","objective":"p75-obj-26","tags":["traitement"],"difficulty":1,"question":"Par combien les substituts nicotiniques multiplient-ils les chances de succès du sevrage par rapport à un placebo ?","answer":"Ils les doublent (× 2)","accept":["x2","x 2","doublent","par 2","par deux","2 fois"],"keywords":["doubl"],"explanation":"Ils doublent les chances de succès, à condition d'être prescrits à la bonne dose et suffisamment longtemps.","src":"p. 13-14"},{"id":"p75-qroc-032","type":"QROC","rank":"A","objective":"p75-obj-26","tags":["traitement"],"difficulty":1,"question":"Qui peut prescrire des substituts nicotiniques ?","answer":"Tout professionnel de santé ayant un numéro RPPS","accept":["tout professionnel de santé","tous les professionnels de santé","professionnel de santé avec un rpps","professionnel de santé disposant d'un numéro rpps"],"keywords":["professionnel"],"explanation":"La prescription est ouverte à tout professionnel de santé disposant d'un numéro RPPS, y compris les infirmiers et les kinésithérapeutes.","src":"p. 13"},{"id":"p75-qroc-033","type":"QROC","rank":"A","objective":"p75-obj-26","tags":["traitement"],"difficulty":2,"question":"À quoi doit être adaptée la dose de substituts nicotiniques ?","answer":"À la consommation réelle du patient (pas de dose maximale)","accept":["consommation réelle","à la consommation réelle du patient","consommation du patient","nombre de cigarettes fumées"],"keywords":["consommation"],"explanation":"Une cigarette manufacturée apporte environ 1 mg de nicotine ; il n'y a pas de dose maximale si elle correspond à la consommation réelle (exemple du Collège : 3 paquets par jour = 3 patchs à 21 mg/24 h).","src":"p. 14"},{"id":"p75-qroc-034","type":"QROC","rank":"A","objective":"p75-obj-26","tags":["traitement","clinique"],"difficulty":2,"question":"À quoi reconnaît-on un sous-dosage en substituts nicotiniques ?","answer":"Aux signes du manque (signes de sevrage)","accept":["signes du manque","signes de manque","signes de sevrage","symptômes de sevrage"],"keywords":["manque"],"explanation":"Les signes de sous-dosage sont ceux du manque ; les signes de surdosage (céphalées, palpitations, nausées, hoquet, dysgueusie...) régressent vite après retrait du dispositif.","src":"p. 14"},{"id":"p75-qroc-035","type":"QROC","rank":"A","objective":"p75-obj-26","tags":["traitement","pièges"],"difficulty":2,"question":"Un patient sous patch nicotinique rallume une cigarette. Que traduit le plus souvent cet événement ?","answer":"Un sous-dosage en substituts (pas un échec du sevrage)","accept":["sous-dosage","sous dosage","un sous-dosage","sous-dosage en substituts nicotiniques"],"keywords":["sous"],"explanation":"Il ne faut pas retirer le patch : cela ne met pas le patient en danger (signes de surdosage possibles) et ne signe pas l'échec. On ajoute un substitut à libération immédiate à chaque envie de fumer.","src":"p. 14"},{"id":"p75-qroc-036","type":"QROC","rank":"A","objective":"p75-obj-26","tags":["traitement"],"difficulty":1,"question":"Comment appelle-t-on l'approche relationnelle centrée sur le patient qui vise à susciter ou à renforcer sa motivation au changement ?","answer":"L'entretien motivationnel","accept":["entretien motivationnel","l'entretien motivationnel"],"keywords":["motivationnel"],"explanation":"C'est le volet « motivation » de l'accompagnement psychologique, systématiquement recommandé ; on y présente les bénéfices de l'arrêt (par exemple : risque d'infarctus diminué de moitié à 1 an).","src":"p. 14-15"},{"id":"p75-qroc-037","type":"QROC","rank":"A","objective":"p75-obj-11","tags":["définition","pièges"],"difficulty":2,"question":"Comment doivent être considérés les produits du tabac chauffé, à ne pas confondre avec la cigarette électronique ?","answer":"Comme des cigarettes : ils ne peuvent pas être conseillés","accept":["comme des cigarettes","assimilés à des cigarettes","comme du tabac","ne peuvent pas être conseillés"],"keywords":["cigarette"],"explanation":"Les produits du tabac chauffé sont inhalés après combustion incomplète ; la cigarette électronique, elle, n'a pas de combustion et peut être utile comme outil de sevrage.","src":"p. 7, 15"},{"id":"p75-qroc-038","type":"QROC","rank":"B","objective":"p75-obj-03","tags":["définition"],"difficulty":1,"question":"De quels trois éléments se compose une cigarette électronique (vaporisateur personnel) ?","answer":"Une batterie, une cartouche de liquide, une résistance","accept":["batterie, cartouche et résistance","batterie cartouche résistance","batterie, cartouche de liquide et résistance"],"keywords":["batterie","résistance"],"explanation":"Le liquide chauffé, mélangé à l'air inspiré, est inhalé sous forme de vapeur ; faute de combustion, la cigarette électronique ne dégage ni CO ni goudrons.","src":"p. 15"},{"id":"p75-qroc-039","type":"QROC","rank":"A","objective":"p75-obj-25","tags":["prévention"],"difficulty":1,"question":"Quelle mesure de prévention est l'un des facteurs les plus efficaces pour réduire le nombre de fumeurs ?","answer":"L'augmentation dissuasive et répétée des prix","accept":["prix","augmentation des prix","hausse des prix","augmentation du prix","augmentation du prix du tabac"],"keywords":["prix"],"explanation":"Le prix de tous les produits du tabac (tabac à rouler compris) doit être augmenté de façon dissuasive et répétée ; s'y ajoutent l'interdiction de la publicité, la protection contre le tabagisme passif et la dénormalisation (paquet neutre).","src":"p. 16"},{"id":"p75-qroc-040","type":"QROC","rank":"A","objective":"p75-obj-17","tags":["épidémiologie","complications"],"difficulty":2,"question":"De combien le tabagisme passif augmente-t-il le risque relatif de cancer du poumon ?","answer":"De 26 %","accept":["26 %","26%","26","de 26 %"],"keywords":["26"],"explanation":"Le tabagisme passif augmente de 26 % le risque relatif de cancer du poumon et de 20 à 30 % celui de décès par maladie cardio-vasculaire.","src":"p. 9"},{"id":"p75-qroc-041","type":"QROC","rank":"A","objective":"p75-obj-01","tags":["complications","pédiatrie"],"difficulty":1,"question":"Quel événement grave du nourrisson est favorisé par le tabagisme passif ?","answer":"La mort subite du nourrisson","accept":["mort subite du nourrisson","mort subite","msn"],"keywords":["mort subite"],"explanation":"Chez l'enfant et le nourrisson, le tabagisme passif majore aussi le risque d'infections ORL et pulmonaires.","src":"p. 10"},{"id":"p75-qroc-042","type":"QROC","rank":"A","objective":"p75-obj-10","tags":["grossesse","complications"],"difficulty":1,"question":"Quelle anomalie de la croissance du fœtus est favorisée par le tabagisme pendant la grossesse ?","answer":"Le retard de croissance intra-utérin (RCIU)","accept":["retard de croissance intra-utérin","rciu","retard de croissance"],"keywords":["retard de croissance"],"explanation":"Le tabagisme pendant la grossesse augmente aussi les fausses couches, les grossesses extra-utérines et les accouchements prématurés.","src":"p. 10"},{"id":"p75-qroc-043","type":"QROC","rank":"A","objective":"p75-obj-22","tags":["biologie","complications"],"difficulty":2,"question":"Quelles anomalies de l'hémogramme sont classiquement induites par le tabagisme ?","answer":"Polyglobulie et polynucléose neutrophile","accept":["polyglobulie et polynucléose neutrophile","polyglobulie, polynucléose neutrophile","polyglobulie polynucléose"],"keywords":["polyglobul","polynucl"],"explanation":"Ces deux anomalies figurent parmi les autres conséquences du tabac, à côté des atteintes cardio-vasculaires, respiratoires, bucco-dentaires, cutanées, psychiatriques et sexuelles.","src":"p. 10"},{"id":"p75-qroc-044","type":"QROC","rank":"B","objective":"p75-obj-23","tags":["clinique","pièges"],"difficulty":1,"question":"Quelle consommation associée est un facteur de risque de rechute du tabagisme et un stimulus déclencheur de l'envie de fumer ?","answer":"L'alcool","accept":["alcool","l'alcool","la consommation d'alcool"],"keywords":["alcool"],"explanation":"La recherche d'autres produits psychoactifs est systématique : l'alcool favorise la rechute, le cannabis peut gêner l'arrêt et les autres substances nécessitent une prise en charge spécialisée.","src":"p. 13"},{"id":"p75-qroc-045","type":"QROC","rank":"A","objective":"p75-obj-09","tags":["épidémiologie"],"difficulty":2,"question":"En France en 2021, quelle proportion des hommes et des femmes de 18 à 75 ans fume ?","answer":"Hommes : 34,7 % ; femmes : 29,2 %","accept":["34,7 % et 29,2 %","35 % et 29 %","34,7 % chez les hommes et 29,2 % chez les femmes","environ 35 % des hommes et 29 % des femmes"],"keywords":["34","29"],"explanation":"Le tabagisme est un peu plus fréquent chez les hommes ; parmi les fumeurs quotidiens : 27,8 % des hommes et 23 % des femmes. La ré-augmentation depuis 2020 est particulièrement liée au tabagisme des femmes.","src":"p. 7"},{"id":"p75-qcm-101","type":"QRM","rank":"A","objective":"p75-obj-20","tags":["diagnostic","définition"],"difficulty":2,"stem":"Selon la CIM-10, on retient le diagnostic de dépendance à une substance lorsqu'au moins trois manifestations sont présentes simultanément au cours de la dernière année. Lesquelles font partie de ces manifestations ?","options":[{"t":"Une diminution progressive du temps passé à se procurer la substance","ok":false,"why":"À l'inverse, le temps passé à se procurer, consommer ou récupérer de la substance augmente."},{"t":"Un désir puissant ou compulsif de consommer la substance","ok":true,"why":"C'est la première manifestation de la liste."},{"t":"Un syndrome de sevrage physiologique à la baisse ou à l'arrêt de la consommation","ok":true,"why":"Le sevrage physiologique fait partie des critères."},{"t":"Un arrêt spontané de la consommation dès les premières conséquences nocives","ok":false,"why":"Le critère est au contraire la poursuite de la consommation malgré des conséquences manifestement nocives."},{"t":"Une tolérance : il faut des quantités croissantes pour obtenir le même effet","ok":true,"why":"La tolérance est un critère de dépendance."}],"explanation":"Les six manifestations sont : désir compulsif, difficulté à contrôler l'usage, sevrage physiologique, tolérance, abandon des autres sources de plaisir avec temps accru consacré à la substance, poursuite malgré les conséquences nocives.","trap":"Deux propositions inversent des critères réels (temps passé, poursuite malgré les dommages).","src":"p. 6"},{"id":"p75-qcm-102","type":"QRM","rank":"A","objective":"p75-obj-21","tags":["clinique"],"difficulty":1,"stem":"Une patiente de 35 ans, fumeuse, arrête brutalement le tabac sans aucun traitement. Quelles manifestations peut-elle présenter dans les jours qui suivent au titre du syndrome de sevrage ?","options":[{"t":"Irritabilité et insomnie","ok":true,"why":"Ils font partie des signes de sevrage, dus à la chute de la nicotinémie."},{"t":"Hoquet et dysgueusie","ok":false,"why":"Ce sont des signes de surdosage en nicotine (substituts), pas des signes de sevrage."},{"t":"Disparition immédiate et définitive de la toux","ok":false,"why":"La toux diminue en quelques semaines, avec une recrudescence temporaire quasi systématique à l'arrêt."},{"t":"Augmentation de l'appétit avec prise de poids","ok":true,"why":"L'appétit accru et la prise de poids font partie des signes de sevrage."},{"t":"Hypersécrétion salivaire et stomatite","ok":false,"why":"Ce sont aussi des signes de surdosage en nicotine."}],"explanation":"Le sevrage associe trouble de l'humeur, céphalées, insomnie, irritabilité, cauchemars, frustration, colère, anxiété, nervosité, difficultés de concentration, appétit accru et/ou prise de poids ; il est le principal facteur de rechute.","trap":"Ne pas confondre les signes de sevrage (manque) avec les signes de surdosage en nicotine.","src":"p. 13-15"},{"id":"p75-qcm-103","type":"QRM","rank":"A","objective":"p75-obj-26","tags":["traitement","pièges"],"difficulty":2,"stem":"Un homme de 55 ans, fumeur très dépendant à la nicotine, est hospitalisé pour un infarctus du myocarde. Que peut-on dire des substituts nicotiniques chez ce patient ?","options":[{"t":"Leur indication est quasi systématique dès qu'il existe une dépendance à la nicotine","ok":true,"why":"L'indication est large dans le sevrage dès qu'il y a une dépendance."},{"t":"Ils sont contre-indiqués pendant les trois mois qui suivent l'infarctus","ok":false,"why":"Ils n'ont globalement aucune contre-indication, y compris après un événement cardio-vasculaire aigu."},{"t":"Un infirmier disposant d'un numéro RPPS peut les prescrire","ok":true,"why":"Infirmiers et kinésithérapeutes peuvent prescrire s'ils disposent d'un numéro RPPS."},{"t":"Seul un tabacologue est autorisé à les prescrire","ok":false,"why":"Tout professionnel de santé disposant d'un numéro RPPS peut les prescrire."},{"t":"Ils ne sont pas contre-indiqués après un événement cardio-vasculaire aigu","ok":true,"why":"Le Collège précise l'absence de contre-indication y compris dans ce contexte."}],"explanation":"Les substituts nicotiniques ont une indication large, doublent les chances de succès du sevrage et n'ont globalement aucune contre-indication (événement cardio-vasculaire aigu, grossesse) ; tout professionnel avec un numéro RPPS peut les prescrire.","trap":"Un infarctus récent n'est pas une contre-indication aux substituts nicotiniques.","src":"p. 13"},{"id":"p75-qcm-104","type":"QRM","rank":"A","objective":"p75-obj-26","tags":["traitement","clinique"],"difficulty":2,"stem":"Un patient sous substituts nicotiniques présente des céphalées, des palpitations et des nausées. Quelle proposition est exacte ?","options":[{"t":"Ces signes traduisent un sous-dosage : il faut augmenter la dose du substitut","ok":false,"why":"Le sous-dosage se manifeste par les signes du manque, non par ces symptômes."},{"t":"Ils contre-indiquent définitivement tout traitement substitutif nicotinique","ok":false,"why":"Ces signes régressent après retrait du dispositif ; il n'existe globalement aucune contre-indication."},{"t":"Ce sont des signes de surdosage, régressifs après retrait du dispositif","ok":true,"why":"Céphalées, palpitations et nausées figurent parmi les signes de surdosage, qui régressent rapidement."},{"t":"Ils signent l'échec du sevrage tabagique et l'arrêt du traitement","ok":false,"why":"Ce sont des effets indésirables d'un surdosage, pas un échec du sevrage."},{"t":"Ils témoignent d'une intolérance cutanée à la colle du patch","ok":false,"why":"L'intolérance à la colle se traduit par un érythème et un prurit au point d'application."}],"explanation":"Les signes de surdosage (céphalées, palpitations, dysgueusie, hoquet, nausées, dyspepsie, stomatite, hypersécrétion salivaire, sécheresse buccale, cauchemars) régressent vite après le retrait du dispositif ; le sous-dosage donne les signes du manque.","trap":"Sous-dosage = signes du manque ; surdosage = effets indésirables listés ci-dessus.","src":"p. 14"},{"id":"p75-qcm-105","type":"QRM","rank":"A","objective":"p75-obj-11","tags":["définition"],"difficulty":2,"stem":"Parmi les modes de consommation de la nicotine suivants, lesquels sont inhalés après une combustion à haute température ?","options":[{"t":"Le cigarillo","ok":true,"why":"Cigarettes, cigarillos, cigares et pipe sont fumés après combustion à haute température."},{"t":"Le snus","ok":false,"why":"Le snus est un tabac humide en sachet, placé entre la gencive et la lèvre supérieure : il est ingéré."},{"t":"La cigarette électronique","ok":false,"why":"Elle est inhalée sans combustion."},{"t":"La chicha (pipe à eau)","ok":true,"why":"Elle fait partie des modes inhalés après combustion à haute température."},{"t":"Les produits du tabac chauffé","ok":false,"why":"Ils sont inhalés après une combustion incomplète."}],"explanation":"Combustion à haute température : cigarettes manufacturées ou roulées, cigarillos, cigares, pipe, chicha. Combustion incomplète : tabac chauffé. Sans combustion : cigarette électronique (dont les puffs jetables). Ingéré : snus, tabac à chiquer.","src":"p. 7"},{"id":"p75-qcm-106","type":"QRM","rank":"A","objective":"p75-obj-11","tags":["définition","pièges"],"difficulty":2,"stem":"À propos du tabac chauffé et de la cigarette électronique, quelles propositions sont exactes ?","options":[{"t":"Les puffs correspondent à des produits du tabac chauffé jetables","ok":false,"why":"Les puffs sont des cigarettes électroniques jetables."},{"t":"Il est conseillé à un non-fumeur de débuter la cigarette électronique avec nicotine","ok":false,"why":"Il est déconseillé à un non-fumeur de commencer, a fortiori avec nicotine."},{"t":"Les produits du tabac chauffé sont inhalés après une combustion incomplète","ok":true,"why":"C'est leur mode de consommation, à distinguer de la cigarette électronique."},{"t":"La cigarette électronique dégage du monoxyde de carbone, comme une cigarette","ok":false,"why":"Faute de combustion, elle ne dégage ni CO ni goudrons."},{"t":"Les produits du tabac chauffé doivent être considérés comme des cigarettes","ok":true,"why":"Ils ne peuvent pas être conseillés et ne doivent pas être confondus avec la cigarette électronique."}],"explanation":"Tabac chauffé = combustion incomplète, assimilé aux cigarettes et non conseillé ; cigarette électronique = sans combustion (ni CO ni goudrons), utile comme outil de sevrage avec nicotine mais déconseillée au non-fumeur.","src":"p. 7, 15"},{"id":"p75-qcm-107","type":"QRM","rank":"A","objective":"p75-obj-25","tags":["prévention"],"difficulty":1,"stem":"Parmi les mesures suivantes, lesquelles font partie des principales mesures de prévention recommandées contre le tabagisme ?","options":[{"t":"L'augmentation dissuasive et répétée du prix de tous les produits du tabac","ok":true,"why":"Le prix est l'un des facteurs les plus efficaces pour réduire le nombre de fumeurs."},{"t":"L'interdiction de toute publicité, directe ou indirecte","ok":true,"why":"C'est la première mesure recommandée."},{"t":"La baisse du prix du tabac à rouler pour limiter les achats à l'étranger","ok":false,"why":"Le prix de tous les produits du tabac, tabac à rouler compris, doit au contraire être augmenté."},{"t":"La protection contre l'exposition au tabagisme passif (lieux publics et de travail)","ok":true,"why":"Elle fait partie des mesures recommandées."},{"t":"La dénormalisation du tabagisme (paquet neutre, campagnes d'information)","ok":true,"why":"Le paquet neutre et les campagnes médiatiques en font partie."}],"explanation":"Mesures recommandées : interdiction de la publicité, hausse dissuasive et répétée des prix, protection contre le tabagisme passif, dénormalisation (paquet neutre, campagnes) et éducation/information (avertissements illustrés, Moi(s) sans tabac depuis 2017).","src":"p. 16"},{"id":"p75-qcm-108","type":"QRM","rank":"A","objective":"p75-obj-19","tags":["diagnostic"],"difficulty":2,"stem":"Pour quantifier la consommation de tabac d'un patient, quelles équivalences et définitions le Collège propose-t-il ?","options":[{"t":"1 chicha = 4 cigarettes manufacturées","ok":false,"why":"1 chicha équivaut à 40 cigarettes manufacturées."},{"t":"1 joint de cannabis = 4 cigarettes manufacturées","ok":true,"why":"Équivalence proposée par le Collège."},{"t":"1 cigarette roulée = 2 cigarettes manufacturées","ok":true,"why":"Équivalence proposée par le Collège."},{"t":"1 paquet-année = 1 cigarette par jour pendant 20 ans","ok":false,"why":"Un paquet-année correspond à 1 paquet (20 cigarettes) par jour pendant 1 an."},{"t":"1 cigarillo = 4 cigarettes manufacturées","ok":true,"why":"Équivalence proposée par le Collège."}],"explanation":"Équivalences : 1 cigarette roulée = 2 cigarettes manufacturées ; 1 cigarillo = 4 ; 1 joint de cannabis = 4 ; 1 chicha = 40. Les paquets-années = nombre de paquets de 20 cigarettes par jour × nombre d'années.","src":"p. 11"},{"id":"p75-qcm-109","type":"QRM","rank":"A","objective":"p75-obj-17","tags":["épidémiologie","complications"],"difficulty":1,"stem":"Parmi les risques suivants, lesquels sont majorés par le tabagisme passif ?","options":[{"t":"Le cancer du poumon","ok":true,"why":"Le risque relatif de cancer du poumon augmente de 26 %."},{"t":"Le décès par maladie cardio-vasculaire","ok":true,"why":"Le risque relatif de décès cardio-vasculaire augmente de 20 à 30 %."},{"t":"Aucun : le non-fumeur exposé ne risque rien","ok":false,"why":"Le tabagisme passif majore plusieurs risques cancéreux, cardio-vasculaires et infectieux."},{"t":"Les infections ORL et pulmonaires chez l'enfant et le nourrisson","ok":true,"why":"Le tabagisme passif favorise ces infections chez le petit."},{"t":"La mort subite du nourrisson","ok":true,"why":"Le tabagisme passif augmente son risque."}],"explanation":"Tabagisme passif : + 26 % de risque relatif de cancer du poumon, + 20 à 30 % de décès cardio-vasculaire, infections ORL et pulmonaires de l'enfant et du nourrisson, mort subite du nourrisson ; il fait aussi partie des facteurs d'exacerbation de l'asthme.","src":"p. 9-10"},{"id":"p75-qcm-110","type":"QRM","rank":"A","objective":"p75-obj-10","tags":["grossesse","prévention"],"difficulty":2,"stem":"Une femme enceinte de 30 ans fume 10 cigarettes par jour et ne se sent pas prête à arrêter. Quelles propositions sont exactes ?","options":[{"t":"Le tabagisme maternel augmente le risque de retard de croissance intra-utérin","ok":true,"why":"Le retard de croissance intra-utérin fait partie des risques du tabagisme pendant la grossesse."},{"t":"Il faut attendre l'accouchement pour proposer un sevrage","ok":false,"why":"L'arrêt doit être organisé quelle que soit la motivation, plus particulièrement en cas de grossesse."},{"t":"Les substituts nicotiniques ne sont pas contre-indiqués chez la femme enceinte","ok":true,"why":"Les substituts n'ont globalement aucune contre-indication, y compris pendant la grossesse."},{"t":"Le tabac augmente le risque d'accouchement prématuré mais pas celui de fausse couche","ok":false,"why":"Il augmente à la fois les fausses couches, les retards de croissance intra-utérin, les grossesses extra-utérines et les accouchements prématurés."},{"t":"Un sevrage doit lui être proposé, même si sa motivation est faible","ok":true,"why":"L'arrêt est à organiser quelle que soit la motivation, la grossesse étant une situation prioritaire."}],"explanation":"Le tabac majore les fausses couches, les retards de croissance intra-utérins, les grossesses extra-utérines et les accouchements prématurés. La grossesse impose une attention particulière pour le sevrage, avec des substituts non contre-indiqués.","src":"p. 5, 10, 13"},{"id":"p75-qcm-111","type":"QRM","rank":"A","objective":"p75-obj-21","tags":["suivi","clinique"],"difficulty":2,"stem":"Parmi les éléments suivants, lesquels sont des facteurs prédictifs de succès de l'arrêt du tabac ?","options":[{"t":"Un long délai entre le réveil et la première cigarette","ok":true,"why":"Un long délai éveil-première cigarette fait partie des facteurs prédictifs de succès."},{"t":"Un âge de début précoce du tabagisme","ok":false,"why":"C'est un âge de début tardif qui est prédictif de succès."},{"t":"La présence d'un entourage fumeur proche du patient","ok":false,"why":"C'est l'absence d'entourage fumeur qui est favorable."},{"t":"Une forte motivation à l'arrêt","ok":true,"why":"La motivation forte est un facteur prédictif de succès."},{"t":"Une consommation d'alcool élevée et régulière","ok":false,"why":"Une faible consommation d'alcool est favorable ; l'alcool favorise la rechute."}],"explanation":"Facteurs prédictifs de succès : bon niveau socio-économique, faible consommation de tabac, absence d'entourage fumeur, faible consommation d'alcool, âge de début tardif, durée d'usage brève, long délai éveil-première cigarette, forte motivation.","src":"p. 13"},{"id":"p75-qcm-112","type":"QRM","rank":"A","objective":"p75-obj-02","tags":["physiopathologie","définition"],"difficulty":2,"stem":"À propos de la dépendance physique (pharmacologique) au tabac, quelle proposition est exacte ?","options":[{"t":"Elle est liée aux goudrons, principales substances actives de la fumée de tabac","ok":false,"why":"Les goudrons sont responsables des cancers ; la dépendance est liée à la nicotine."},{"t":"La nicotine atteint très vite le cerveau et stimule les systèmes de récompense","ok":true,"why":"C'est le mécanisme de la dépendance pharmacologique (fixation sur les récepteurs cholinergiques nicotiniques, libération de dopamine)."},{"t":"Elle n'apparaît qu'après plusieurs années de consommation importante de tabac","ok":false,"why":"Elle peut apparaître dès les premières semaines d'exposition, même pour une faible consommation."},{"t":"Elle se mesure par le taux de monoxyde de carbone dans l'air expiré du patient","ok":false,"why":"Le CO expiré reflète un tabagisme récent ; la dépendance physique s'évalue par le test de Fagerström."},{"t":"Elle correspond aux envies réflexes déclenchées par les moments de convivialité","ok":false,"why":"Ces envies relèvent de la dépendance comportementale (ou sociale)."}],"explanation":"La nicotine, qui gagne très rapidement le cerveau quand elle est fumée, se fixe sur les récepteurs cholinergiques nicotiniques et stimule les systèmes de récompense ; la dépendance peut s'installer dès les premières semaines.","src":"p. 6, 12"},{"id":"p75-qcm-113","type":"QRM","rank":"B","objective":"p75-obj-05","tags":["physiopathologie","complications"],"difficulty":2,"stem":"Parmi les mécanismes suivants, lesquels participent à l'atteinte artérielle induite par le tabac ?","options":[{"t":"Une dysfonction endothéliale entraînée par la fumée de tabac","ok":true,"why":"Elle fait partie des mécanismes de l'atteinte artérielle."},{"t":"Une diminution de l'agrégation plaquettaire","ok":false,"why":"La fumée favorise au contraire l'agrégation plaquettaire."},{"t":"Une hypoxie liée à la fixation du CO sur l'hémoglobine","ok":true,"why":"Elle participe aux lésions endothéliales et donc aux complications cardio-vasculaires."},{"t":"Une réduction des lésions endothéliales grâce au monoxyde de carbone","ok":false,"why":"Le CO crée une hypoxie qui participe aux lésions endothéliales."},{"t":"Une augmentation de l'agrégation plaquettaire","ok":true,"why":"Elle accroît les thromboses artérielles."}],"explanation":"La fumée entraîne une dysfonction endothéliale et favorise l'agrégation plaquettaire (thromboses artérielles) ; le CO, fixé sur l'hémoglobine, crée une hypoxie qui participe aux lésions endothéliales.","src":"p. 7, 9"},{"id":"p75-qcm-114","type":"QRM","rank":"A","objective":"p75-obj-26","tags":["suivi","prévention"],"difficulty":2,"stem":"Lors d'un entretien motivationnel, vous présentez à un fumeur les bénéfices de l'arrêt du tabac. Quelle proposition est exacte ?","options":[{"t":"Dès 8 heures, il n'y a plus de nicotine dans le corps","ok":false,"why":"En 8 h, le CO sanguin diminue de moitié ; la nicotine disparaît en 2 jours."},{"t":"Dès 20 minutes, le taux de CO sanguin est divisé par deux","ok":false,"why":"En 20 minutes, la fréquence cardiaque et la tension artérielle s'améliorent ; le CO diminue de moitié en 8 h."},{"t":"Une recrudescence de la toux à l'arrêt n'est jamais observée","ok":false,"why":"Elle est quasi systématique et temporaire (ré-épithélialisation bronchique, reconstitution des cellules ciliées)."},{"t":"À 1 an, le risque d'infarctus est diminué de moitié","ok":true,"why":"À 1 an, le risque d'accident vasculaire cérébral a nettement baissé et celui d'infarctus du myocarde est réduit de moitié."},{"t":"À 10 ans, l'espérance de vie reste inchangée","ok":false,"why":"À 10 ans, le risque de cancer diminue et l'espérance de vie augmente."}],"explanation":"Chronologie : 20 min (fréquence cardiaque et tension), 8 h (CO divisé par 2), 2 jours (plus de nicotine, goût et odorat), quelques semaines (toux, peau), quelques mois (souffle, sport), 1 an (infarctus divisé par 2), 10 ans (cancer, espérance de vie).","src":"p. 15"},{"id":"p75-qcm-115","type":"QRM","rank":"A","objective":"p75-obj-19","tags":["diagnostic","prévention"],"difficulty":1,"stem":"À propos du repérage précoce et du conseil minimal d'arrêt du tabac, quelles propositions sont exactes ?","options":[{"t":"Tous les professionnels de santé sont concernés, systématiquement","ok":true,"why":"Le repérage précoce est systématique, quel que soit le professionnel."},{"t":"Ils sont réservés aux fumeurs qui se disent déjà décidés à arrêter","ok":false,"why":"Ils concernent tous les patients, quelle que soit leur motivation."},{"t":"Le premier temps est de demander au patient s'il fume du tabac","ok":true,"why":"Le premier temps est l'évaluation de la consommation déclarée (« fumez-vous du tabac ? »)."},{"t":"Ils n'ont pas d'effet démontré sur le taux de sevrage des patients","ok":false,"why":"Le conseil minimal permet d'augmenter le taux de sevrage."},{"t":"Ils sont inutiles chez un patient qui déclare ne pas fumer actuellement","ok":false,"why":"On lui demande alors s'il a déjà fumé, pendant combien de temps et depuis quand il a arrêté."}],"explanation":"Le repérage précoce (conseil minimal) se fait en deux temps : consommation déclarée, puis évaluation du risque et conseil d'arrêt ; si le patient ne fume pas, on cherche un tabagisme passé. Le conseil minimal augmente le taux de sevrage.","src":"p. 10-11"},{"id":"p75-qcm-116","type":"QRM","rank":"B","objective":"p75-obj-23","tags":["clinique","pièges"],"difficulty":2,"stem":"Chez un patient fumeur qui souhaite arrêter, que doit-on faire concernant les autres produits psychoactifs ?","options":[{"t":"Les rechercher uniquement s'il a des antécédents psychiatriques","ok":false,"why":"La recherche doit être systématique."},{"t":"Considérer que l'alcool est sans effet sur l'envie de fumer","ok":false,"why":"La prise d'alcool est un stimulus déclencheur de l'envie de fumer et un facteur de rechute."},{"t":"Considérer que le cannabis n'influence jamais l'arrêt du tabac","ok":false,"why":"Le cannabis peut gêner l'arrêt du tabac."},{"t":"Traiter toutes les autres substances comme le tabac, sans prise en charge spécialisée","ok":false,"why":"Les autres substances nécessitent une prise en charge spécialisée."},{"t":"Les rechercher systématiquement : l'alcool favorise la rechute","ok":true,"why":"La recherche est systématique ; l'alcool favorise la rechute et le cannabis peut gêner l'arrêt."}],"explanation":"La recherche d'autres produits psychoactifs est systématique : alcool (rechute, envie de fumer), cannabis (peut gêner l'arrêt), autres substances (prise en charge spécialisée).","src":"p. 13"},{"id":"p75-qcm-117","type":"QRM","rank":"A","objective":"p75-obj-09","tags":["épidémiologie"],"difficulty":2,"stem":"À propos de l'épidémiologie du tabagisme en France en 2021 chez les 18-75 ans, quelles propositions sont exactes ?","options":[{"t":"La prévalence est la plus élevée chez les titulaires d'un diplôme supérieur au baccalauréat","ok":false,"why":"Elle est plus élevée quand le diplôme est plus faible (35,8 % sans diplôme contre 17,3 % au-dessus du bac)."},{"t":"Le tabagisme est un peu plus fréquent chez les hommes que chez les femmes","ok":true,"why":"34,7 % des hommes contre 29,2 % des femmes fument."},{"t":"Le tabagisme des femmes a diminué entre 2019 et 2021","ok":false,"why":"Il est passé de 20,7 % à 23 % : la ré-augmentation est particulièrement liée aux femmes."},{"t":"On compte environ 12 millions de fumeurs quotidiens","ok":true,"why":"15 millions de fumeurs, dont 12 millions de fumeurs quotidiens."},{"t":"La prévalence continue de baisser régulièrement depuis 2017","ok":false,"why":"Après une baisse importante à partir de 2017, une ré-augmentation est observée depuis 2020."}],"explanation":"En 2021 : 15 millions de fumeurs (34,7 % des hommes, 29,2 % des femmes), dont 12 millions quotidiens. Baisse à partir de 2017, ré-augmentation depuis 2020, surtout chez les femmes et les personnes peu diplômées.","src":"p. 7-8"},{"id":"p75-qru-101","type":"QRU","rank":"A","objective":"p75-obj-20","tags":["diagnostic"],"difficulty":2,"stem":"Un homme de 38 ans fume environ 25 cigarettes par jour et allume sa première cigarette 10 minutes après le réveil. Quelle est l'interprétation du test de Fagerström simplifié (2 questions) ?","options":[{"t":"Non dépendant à la nicotine","ok":false,"why":"Ce résultat correspond à un score de 0 à 1."},{"t":"Dépendance modérée à la nicotine","ok":false,"why":"Elle correspond à un score de 2 à 3."},{"t":"Dépendance très forte à la nicotine","ok":false,"why":"La version simplifiée ne comporte que trois paliers (0-1, 2-3, 4-6) ; « forte ou très forte » concerne le test complet (7 à 10)."},{"t":"Dépendance forte à la nicotine","ok":true,"why":"21 à 30 cigarettes par jour = 2 points ; première cigarette entre 6 et 30 minutes après le réveil = 2 points ; total 4, soit dépendance forte."},{"t":"Le test simplifié ne permet pas de conclure","ok":false,"why":"Ses deux questions suffisent pour interpréter le score."}],"explanation":"Quantité (21 à 30 par jour = 2 points) + délai (6 à 30 minutes = 2 points) = 4, soit une dépendance forte (4 à 6).","src":"p. 12"},{"id":"p75-qru-102","type":"QRU","rank":"A","objective":"p75-obj-19","tags":["pièges","épidémiologie"],"difficulty":2,"stem":"Deux patients ont chacun 10 paquets-années : le premier a fumé 10 cigarettes par jour pendant 20 ans, le second 20 cigarettes par jour pendant 10 ans. Que peut-on en conclure ?","options":[{"t":"Leur risque de cancer est identique puisque leur consommation en paquets-années est la même","ok":false,"why":"Le Collège insiste sur le fait qu'ils ne sont pas du tout équivalents."},{"t":"Leurs risques diffèrent : la durée d'exposition pèse plus que la quantité quotidienne","ok":true,"why":"La durée multiplie le risque avec un facteur à la puissance 4, la quantité avec un facteur à la puissance 2."},{"t":"Le risque dépend surtout de la quantité quotidienne, donc le second est le plus exposé","ok":false,"why":"La quantité agit à la puissance 2, la durée à la puissance 4 : la durée pèse davantage."},{"t":"Seul le second est réellement exposé, car il fume un paquet entier par jour","ok":false,"why":"Il n'existe pas de seuil en dessous duquel fumer ne représente aucun risque."},{"t":"Le paquet-année est le meilleur évaluateur du risque tabagique","ok":false,"why":"Le paquet-année n'est pas un très bon évaluateur du risque."}],"explanation":"Quantité → puissance 2 ; durée → puissance 4 : à nombre de paquets-années égal, les risques ne sont pas équivalents, ce qui limite l'intérêt de cette unité.","src":"p. 11-12"},{"id":"p75-qru-103","type":"QRU","rank":"A","objective":"p75-obj-26","tags":["traitement"],"difficulty":2,"stem":"Un patient fume 2 paquets de cigarettes manufacturées par jour. Quelle prescription de patchs est cohérente avec les principes de dosage du Collège ?","options":[{"t":"1 patch à 7 mg/24 h","ok":false,"why":"Dose très inférieure à la consommation réelle : risque de sous-dosage."},{"t":"1 patch à 21 mg/24 h, car il existe une dose maximale quotidienne","ok":false,"why":"Il n'y a pas de dose maximale si elle est adaptée à la consommation réelle."},{"t":"2 patchs à 21 mg/24 h","ok":true,"why":"1 cigarette apporte environ 1 mg de nicotine : 40 cigarettes, soit environ 2 patchs à 21 mg (exemple du Collège : 3 paquets = 3 patchs)."},{"t":"Pas de patch : uniquement des formes à libération immédiate","ok":false,"why":"Le traitement associe une forme à libération prolongée (patch) et, au besoin, des formes à libération immédiate."},{"t":"3 patchs à 21 mg/24 h","ok":false,"why":"C'est la dose de l'exemple du Collège pour 3 paquets par jour, donc excessive ici."}],"explanation":"La dose est adaptée à la consommation réelle (1 cigarette ≈ 1 mg de nicotine), sans dose maximale ; l'exemple du Collège associe 3 paquets par jour à 3 patchs de 21 mg/24 h.","src":"p. 14"},{"id":"p75-qru-104","type":"QRU","rank":"A","objective":"p75-obj-19","tags":["définition"],"difficulty":1,"stem":"Un patient de 45 ans dit n'avoir fumé que 40 cigarettes au cours de toute sa vie. Quel est son statut tabagique selon les définitions du Collège ?","options":[{"t":"Non-fumeur (jamais fumeur)","ok":true,"why":"Un non-fumeur a fumé moins de 100 cigarettes au cours de sa vie."},{"t":"Fumeur actif (non sevré depuis 12 mois)","ok":false,"why":"Il n'est pas fumeur : il a fumé moins de 100 cigarettes dans sa vie."},{"t":"Ex-fumeur (fumeur sevré)","ok":false,"why":"L'ex-fumeur a arrêté totalement et définitivement depuis plusieurs mois (12 mois le plus souvent) après avoir fumé."},{"t":"Fumeur passif (exposé à la fumée d'autrui)","ok":false,"why":"Le tabagisme passif est l'exposition à la fumée des autres ; il ne se définit pas par le nombre de cigarettes fumées."},{"t":"Dépendant au tabac","ok":false,"why":"Rien n'indique une dépendance : il faut au moins 3 manifestations sur la dernière année."}],"explanation":"Non-fumeur = moins de 100 cigarettes au cours de la vie ; ex-fumeur = arrêt total et définitif depuis plusieurs mois (12 mois le plus souvent) ; fumeur actif = non sevré depuis 12 mois.","src":"p. 6-7"},{"id":"p75-qru-105","type":"QRU","rank":"A","objective":"p75-obj-06","tags":["épidémiologie"],"difficulty":1,"stem":"Dans le monde, combien de décès par an sont attribuables au tabac, dont combien au tabagisme passif ?","options":[{"t":"Environ 75 000, dont 12 000 liés au tabagisme passif","ok":false,"why":"75 000 correspond aux décès annuels attribuables au tabac en France."},{"t":"Environ 1,3 million, dont 120 000 liés au tabagisme passif","ok":false,"why":"1,3 milliard est le nombre de fumeurs dans le monde, pas le nombre de décès."},{"t":"Plus de 8 millions, dont 12 000 liés au tabagisme passif","ok":false,"why":"Le tabagisme passif représente 1,2 million de décès, pas 12 000."},{"t":"Plus de 13 millions, dont 1,2 million liés au tabagisme passif","ok":false,"why":"Le total mondial est de plus de 8 millions de décès par an."},{"t":"Plus de 8 millions, dont 1,2 million liés au tabagisme passif","ok":true,"why":"Chiffres de l'OMS rapportés par le Collège."}],"explanation":"Selon l'OMS, plus de 8 millions de décès annuels dans le monde sont attribuables au tabac, dont 1,2 million au tabagisme passif ; on compte 1,3 milliard de fumeurs, dont plus de 80 % dans des pays à revenu faible ou intermédiaire.","src":"p. 7, 9"},{"id":"p75-qru-106","type":"QRU","rank":"B","objective":"p75-obj-03","tags":["définition"],"difficulty":2,"stem":"Parmi les éléments suivants, lequel ne fait pas partie de la composition du liquide d'une cigarette électronique ?","options":[{"t":"Des substances aromatiques","ok":false,"why":"Le liquide contient des arômes variés (tabac, menthe, pomme...)."},{"t":"Du propylène glycol","ok":false,"why":"Le propylène glycol fait partie du liquide."},{"t":"Des goudrons","ok":true,"why":"Faute de combustion, la cigarette électronique ne dégage ni goudrons ni CO."},{"t":"De la glycérine végétale","ok":false,"why":"La glycérine végétale fait partie du liquide."},{"t":"Des additifs","ok":false,"why":"Le liquide contient aussi des additifs."}],"explanation":"Le liquide contient des arômes, du propylène glycol, de la glycérine végétale et des additifs, avec une concentration de nicotine variable (haute, moyenne, basse) voire nulle ; il n'y a ni CO ni goudrons.","src":"p. 15"},{"id":"p75-qru-107","type":"QRU","rank":"A","objective":"p75-obj-26","tags":["traitement","pièges"],"difficulty":2,"stem":"Une patiente sous patch nicotinique présente un érythème et un prurit à l'endroit où le patch est collé. Quelle conduite est proposée ?","options":[{"t":"Arrêter définitivement tous les substituts nicotiniques","ok":false,"why":"L'intolérance à la colle se gère sans interrompre le sevrage."},{"t":"Doubler la dose du patch pour compenser la gêne locale","ok":false,"why":"Cela n'a pas de rapport avec l'intolérance cutanée ; la dose dépend de la consommation réelle."},{"t":"Contre-indiquer définitivement l'ensemble des patchs nicotiniques","ok":false,"why":"Les substituts nicotiniques n'ont globalement aucune contre-indication."},{"t":"Changer de dispositif ou le coller sur une zone moins sensible","ok":true,"why":"Par exemple la plante du pied ou l'abdomen."},{"t":"Attendre la disparition spontanée des signes sans changer de patch","ok":false,"why":"Le Collège propose de changer de dispositif ou de zone d'application."}],"explanation":"En cas d'intolérance à la colle (érythème, prurit au point d'application), on peut changer de dispositif ou coller les patchs sur des zones moins sensibles (plante du pied, abdomen...).","src":"p. 14"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p75-pareto","points":[{"id":"p75-par-01","rank":"A","cat":"chiffre","text":"Tabac = **1re cause de mortalité évitable** : ≈ **75 000 décès/an** en France (cancers 46 000, maladies cardio-vasculaires 17 000, respiratoires 12 000) ; **1 fumeur sur 2** meurt d'une maladie liée au tabac","src":"p. 5, 9"},{"id":"p75-par-02","rank":"A","cat":"définition","text":"Dépendance (CIM-10) = **≥ 3 critères** simultanés sur la **dernière année** (désir compulsif, perte de contrôle, sevrage, tolérance...) ; agent de la dépendance = **nicotine**","src":"p. 5-6"},{"id":"p75-par-03","rank":"A","cat":"définition","text":"3 types de dépendance : **physique** (nicotine, récompense), **psychologique** (effets positifs : relaxer, réfléchir, coupe-faim), **comportementale** (situations déclenchantes)","src":"p. 6"},{"id":"p75-par-04","rank":"A","cat":"examen","text":"Fagerström simplifié = 2 questions : **cigarettes/jour** + **délai réveil → 1re cigarette** ; score 0-1 non dépendant, 2-3 modérée, **4-6 forte**","src":"p. 12"},{"id":"p75-par-05","rank":"A","cat":"prévention","text":"**Conseil minimal** à chaque contact (« fumez-vous du tabac ? », RPIB ou 5A), **quelle que soit la motivation** ; relais Tabac Info Service **3989**","src":"p. 5, 10-11"},{"id":"p75-par-06","rank":"A","cat":"traitement","text":"**Substituts nicotiniques** : **aucune contre-indication** (même après infarctus ou enceinte), **× 2** les chances de sevrage, prescriptibles par tout professionnel avec RPPS","src":"p. 5, 13"},{"id":"p75-par-07","rank":"A","cat":"traitement","text":"Dose de substitut : 1 cigarette ≈ **1 mg** de nicotine ; **pas de dose maximale** si adaptée à la consommation (3 paquets/j = 3 patchs **21 mg/24 h**)","src":"p. 14"},{"id":"p75-par-08","rank":"A","cat":"piège","text":"Cigarette fumée **sous patch** = **sous-dosage**, pas un échec → **ne pas retirer** le patch, ajouter un substitut à libération immédiate à chaque envie","src":"p. 14"},{"id":"p75-par-09","rank":"A","cat":"clinique","text":"**Sevrage** dès l'arrêt (chute de la nicotinémie) = 1er facteur de **rechute** : humeur, insomnie, irritabilité, anxiété, ↑ appétit/poids ; **craving** = pulsion à fumer","src":"p. 13"},{"id":"p75-par-10","rank":"A","cat":"chiffre","text":"**1 cancer sur 4** dû au tabac ; **80 %** des cancers du poumon (fumeur : risque × 10-15) ; maladies cardio-vasculaires **× 20** ; pas de seuil sans risque","src":"p. 9"},{"id":"p75-par-11","rank":"A","cat":"définition","text":"**Paquets-années** = paquets (20 cig)/jour × années, évaluateur imparfait : **durée** (puissance 4) > quantité (puissance 2) ; **CO expiré** = marqueur non déclaratif récent","src":"p. 7, 11-12"},{"id":"p75-par-12","rank":"A","cat":"gravité","text":"Tabagisme **passif** : **+ 26 %** de cancer du poumon, + 20-30 % de décès cardio-vasculaires ; enfant : infections ORL/pulmonaires, **mort subite du nourrisson**","src":"p. 9-10"},{"id":"p75-par-13","rank":"A","cat":"gravité","text":"Grossesse : ↑ fausses couches, **retard de croissance**, grossesse extra-utérine, prématurité → sevrage prioritaire, comme avant une **chirurgie programmée** (arrêt **6-8 semaines** avant)","src":"p. 10-11"},{"id":"p75-par-14","rank":"A","cat":"piège","text":"**Tabac chauffé** = comme des cigarettes (non conseillé) ; **cigarette électronique** : **ni CO ni goudrons**, utile au sevrage, déconseillée au non-fumeur","src":"p. 7, 15"},{"id":"p75-par-15","rank":"A","cat":"prévention","text":"Prévention : hausse dissuasive des **prix** (un des leviers les plus efficaces), interdiction de **publicité**, protection du tabagisme passif, **paquet neutre**","src":"p. 16"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
